require_once __DIR__.'/includes/auth.php';
$remote=$_SERVER['REMOTE_ADDR']??'';$localRequest=in_array($remote,['127.0.0.1','::1'],true);$dockerSetup=filter_var(getenv('ALLOW_ADMIN_SETUP')?:'0',FILTER_VALIDATE_BOOLEAN);if(!$localRequest&&!$dockerSetup)errorResponse(403,'إعداد المدير متاح من الجهاز المحلي فقط.');
$adminExists=(bool)db()->query("SELECT id FROM users WHERE role='admin' LIMIT 1")->fetch();if($adminExists){http_response_code(410);exit('تم إنشاء حساب المدير مسبقًا، وقد أُغلق معالج الإعداد.');}$errors=[];
if(isPost()){verifyCsrf();$name=trim($_POST['name']??'');$email=mb_strtolower(trim($_POST['email']??''));$pass=(string)($_POST['password']??'');if(mb_strlen($name)<3)$errors[]='أدخل اسمًا صالحًا.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='البريد غير صالح.';if(strlen($pass)<12||!preg_match('/[A-Z]/',$pass)||!preg_match('/[a-z]/',$pass)||!preg_match('/\d/',$pass))$errors[]='استخدم 12 حرفًا على الأقل مع حرف كبير وصغير ورقم.';if($pass!==($_POST['confirm_password']??''))$errors[]='كلمتا المرور غير متطابقتين.';if(!$errors){$s=db()->prepare("INSERT INTO users(name,email,password,role,status,created_at,updated_at) VALUES(?,?,?,'admin','active',NOW(),NOW())");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);loginUser((int)db()->lastInsertId());redirect(url('admin/dashboard.php'));}}
$pageTitle='إعداد المدير';require __DIR__.'/includes/header.php';?><div class="container auth-shell py-5"><div class="auth-card"><h1 class="h3 fw-bold">إنشاء المدير الأول</h1><p class="text-secondary">هذه الصفحة تعمل محليًا وتُغلق نهائيًا بعد إنشاء المدير.</p><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><form method="post"><?=csrfField()?><input class="form-control mb-3" name="name" placeholder="الاسم الكامل" required><input class="form-control mb-3" type="email" name="email" placeholder="البريد الإلكتروني" required><input class="form-control mb-3" type="password" name="password" placeholder="كلمة مرور قوية" required><input class="form-control mb-4" type="password" name="confirm_password" placeholder="تأكيد كلمة المرور" required><button class="btn btn-primary w-100">إنشاء حساب المدير</button></form></div></div><?php require __DIR__.'/includes/footer.php';?>
